begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select plan(7);
insert into auth.users (id, email) values ('90000000-0000-4000-8000-000000000001', 'owner@example.com'), ('90000000-0000-4000-8000-000000000002', 'stranger@example.com');
insert into public.admin_users (user_id, role, is_active) values ('90000000-0000-4000-8000-000000000001', 'owner', true);
insert into public.categories (id, name, slug, status) values ('91000000-0000-4000-8000-000000000001', 'Sweet', 'sweet', 'published');
insert into public.products (id, category_id, name, slug, base_price_cents, status, is_available) values ('92000000-0000-4000-8000-000000000001', '91000000-0000-4000-8000-000000000001', 'Pastry', 'pastry', 500, 'published', true);
insert into public.product_option_groups (id, product_id, name, selection_type, status) values ('95000000-0000-4000-8000-000000000001', '92000000-0000-4000-8000-000000000001', 'Flavour', 'single', 'published'), ('95000000-0000-4000-8000-000000000002', '92000000-0000-4000-8000-000000000001', 'Private decoration', 'multiple', 'draft');
set local role anon;
select results_eq($$select name from public.product_option_groups where id in ('95000000-0000-4000-8000-000000000001', '95000000-0000-4000-8000-000000000002') order by name$$, array['Flavour'], 'anonymous visitors see published groups only');
select throws_ok($$insert into public.product_option_groups (product_id, name, selection_type) values ('92000000-0000-4000-8000-000000000001', 'Unsafe', 'single')$$, '42501', null, 'anonymous visitors cannot create groups');
set local role authenticated;
set local request.jwt.claim.sub = '90000000-0000-4000-8000-000000000002';
select results_eq($$select name from public.product_option_groups where id in ('95000000-0000-4000-8000-000000000001', '95000000-0000-4000-8000-000000000002') order by name$$, array['Flavour'], 'a non-owner sees published groups only');
select is_empty($$update public.product_option_groups set name = 'Changed' where id = '95000000-0000-4000-8000-000000000001' returning id$$, 'a non-owner cannot update groups');
set local request.jwt.claim.sub = '90000000-0000-4000-8000-000000000001';
select results_eq($$select name from public.product_option_groups where id in ('95000000-0000-4000-8000-000000000001', '95000000-0000-4000-8000-000000000002') order by name$$, array['Flavour', 'Private decoration'], 'the owner sees all group states');
select results_eq($$update public.product_option_groups set name = 'Decoration' where id = '95000000-0000-4000-8000-000000000002' returning name$$, array['Decoration'], 'the owner updates a group');
reset role;
select results_eq($$select name from public.product_option_groups where id = '95000000-0000-4000-8000-000000000001'$$, array['Flavour'], 'the denied update changed nothing');
select * from finish();
rollback;
